using System;using System.Linq;using System.Drawing;using System.Reflection;using System.Windows.Forms;using BeamScheduleFormatter;
class NativeControlStabilityTests {
 sealed class Tabs:NavigationTabs {int creating;internal int MaximumDepth;internal bool DestroyedDuringCreate;protected override void OnHandleCreated(EventArgs e){creating++;MaximumDepth=Math.Max(MaximumDepth,creating);try{base.OnHandleCreated(e);}finally{creating--;}}protected override void OnHandleDestroyed(EventArgs e){if(creating>0)DestroyedDuringCreate=true;base.OnHandleDestroyed(e);}}
 static int checks;static void Check(bool value,string message){checks++;if(!value)throw new Exception(message);}
 [STAThread]static void Main(){Application.EnableVisualStyles();using(var form=new Form{Width=1100,Height=650}){var tabs=new Tabs{Dock=DockStyle.Fill};foreach(string title in new[]{"Reinforced Concrete Works","Carpentry and Joinery Works","Pavement Construction","Slope Protection Works"}){var page=new TabPage(title);var nested=new Tabs{Dock=DockStyle.Fill};nested.TabPages.Add("A longer nested calculation sheet caption");nested.TabPages.Add("Additional worksheet");page.Controls.Add(nested);tabs.TabPages.Add(page);}form.Controls.Add(tabs);PowTheme.Apply(form);form.Show();Application.DoEvents();for(int n=0;n<120;n++){tabs.SelectedIndex=n%tabs.TabCount;form.Width=1000+n%3*100;if(n%10==0)tabs.Font=n%20==0?ModernUi.Strong:ModernUi.Body;Application.DoEvents();}foreach(var control in new[]{tabs}.Concat(tabs.TabPages.Cast<TabPage>().Select(p=>(Tabs)p.Controls[0]))){Check(control.MaximumDepth==1&&!control.DestroyedDuringCreate,"Native tab handles are never recursively recreated during handle creation");for(int i=0;i<control.TabCount;i++)Check(control.GetTabRect(i).Width>=TextRenderer.MeasureText(control.TabPages[i].Text,control.Font,Size.Empty,TextFormatFlags.NoPadding|TextFormatFlags.NoPrefix|TextFormatFlags.SingleLine).Width+16,"Full caption fits after deferred sizing and repeated tab/resize operations");}}
 using(var form=new Form{Width=900,Height=300}){var tools=new FlowLayoutPanel{Dock=DockStyle.Top,AutoSize=true};var button=new Button{Text="Save Bill of Quantities"};int clicks=0;button.Click+=(s,e)=>clicks++;tools.Controls.Add(button);form.Controls.Add(tools);PowTheme.Apply(form);for(int n=0;n<30;n++)PremiumControls.StyleButton(button);form.Show();Application.DoEvents();button.PerformClick();Check(clicks==1,"Repeated button styling preserves one native action per click");button.Text="Open a much longer project configuration description";Application.DoEvents();int expected=TextRenderer.MeasureText(button.Text,button.Font,Size.Empty,TextFormatFlags.SingleLine|TextFormatFlags.NoPrefix).Width+28+22;Check(button.Width>=expected,"Dynamic command caption and icon fit without clipping");button.Enabled=false;button.PerformClick();Check(clicks==1,"Disabled button does not execute");button.Enabled=true;button.Focus();using(var bitmap=new Bitmap(button.Width,button.Height))button.DrawToBitmap(bitmap,button.ClientRectangle);Check(button.Focused&&button.TabStop,"Keyboard focus is retained while native dotted cue is hidden");}
 Console.WriteLine("PASS: "+checks+" native tab lifecycle, sizing and button action/appearance stability checks");}
}
